R_API st64 r_buf_read(RBuffer *b, ut8 *buf, ut64 len) { /* <=== r_buf_read */ 
	r_return_val_if_fail (b && buf, -1);
	st64 r = buf_read (b, buf, len);
	if (r >= 0 && r < len) {
		memset (buf + r, b->Oxff_priv, len - r);
	}
	return r;
}

static RSkipListNode *find_insertpoint(RSkipList *list, void *data, RSkipListNode **updates, bool by_data) { /* <=== find_insertpoint */ 
	RSkipListNode *x = list->head;
	int i;

	for (i = list->list_level; i >= 0; i--) {
		if (by_data) {
			while (x->forward[i] != list->head
				&& list->compare (x->forward[i]->data, data) < 0) {
				x = x->forward[i];
			}
		} else {
			while (x->forward[i] != list->head && x->forward[i] != data) {
				x = x->forward[i];
			}
		}
		if (updates) {
			updates[i] = x;
		}
	}
	x = x->forward[0];
	return x;
}

static RSkipListNode *r_skiplist_node_new(void *data, int level) { /* <=== r_skiplist_node_new */ 
	RSkipListNode *res = R_NEW0 (RSkipListNode);
	if (!res) {
		return NULL;
	}
	res->forward = R_NEWS0 (RSkipListNode *, level + 1);
	if (!res->forward)  {
		free (res);
		return NULL;
	}
	res->data = data;
	return res;
}

static char *get_name(struct MACH0_(obj_t) *mo, ut32 stridx, bool filter) { /* <=== get_name */ 
	size_t i = 0;
	if (!mo->symstr || stridx >= mo->symstrlen) {
		return NULL;
	}
	int len = mo->symstrlen - stridx;
	const char *symstr = (const char*)mo->symstr + stridx;
	for (i = 0; i < len; i++) {
		if ((ut8)(symstr[i] & 0xff) == 0xff || !symstr[i]) {
			len = i;
			break;
		}
	}
	if (len > 0) {
		char *res = r_str_ndup (symstr, len);
		if (filter) {
			r_str_filter (res, -1);
		}
		return res;
	}
	return NULL;
}

